+        }
+        if let Some(flag) = self.values.keys().next() {
+            return Err(format!(
+                "{flag} does not apply to the selected input or agent"
+            ));
+        }
+        Ok(Settings {
+            input,
+            agent,
+            arguments: self.arguments,
+        })
+    }
